// Clear Spring Pill — pure Qi that fights impurity.
hooks.consume = (ctx, result) => {
  const imp = ctx.character.impurity;
  const mult = Math.max(0, 1 - Math.floor(imp / 10) * 0.2);
  if (mult < 1) {
    result.yieldAmount = Math.round(result.yieldAmount * mult * 100) / 100;
    result.notes.push('💧 Your impurity muddies the spring: ' + Math.round(mult * 100) + '% potency.');
  } else {
    result.notes.push('💧 Your meridians are clear — the spring flows fully.');
  }
  return result;
};

// Heaven's Dice Pellet — a gamble. Average potency is about 1.15x, so it is fun, not farmable.
hooks.consume = (ctx, result) => {
  const r = Math.random();
  let mult; let text;
  if (r < 0.25) { mult = 0; text = '🎲 Snake eyes — the pellet was hollow.'; }
  else if (r < 0.70) { mult = 1; text = '🎲 An ordinary roll.'; }
  else if (r < 0.95) { mult = 2; text = '🎲 Lucky! Double potency.'; }
  else { mult = 4; text = '🎲 Heaven smiles — quadruple potency!'; }
  result.yieldAmount = Math.round(result.yieldAmount * mult * 100) / 100;
  result.impurity = Math.round(result.impurity * (0.5 + Math.random()) * 100) / 100;
  result.notes.push(text);
  return result;
};

// Blood Essence Pill — sects that can digest blood essence take half the impurity.
const AFFINE_SECTS = ['Blood Cult'];
hooks.consume = (ctx, result) => {
  if (AFFINE_SECTS.includes(ctx.character.sect)) {
    result.impurity = result.impurity / 2;
    result.notes.push("🩸 Your sect's arts drink the blood essence — half the impurity.");
  }
  return result;
};

// Five Elements Harmony Pill — rewards characters whose cultivation is attuned to elements.
hooks.consume = (ctx, result) => {
  const attuned = Object.values(ctx.character.absorption.byElement || {}).filter((v) => v > 0).length;
  const extra = Math.min(3, attuned);
  if (extra) {
    result.yieldAmount += extra;
    result.notes.push('☯️ ' + extra + ' attuned element(s) resonate: +' + extra + ' Qi.');
  } else {
    result.notes.push('☯️ No element answers the call — only the base yield.');
  }
  return result;
};

// Pill of the Middle Way — always strengthens your weakest stat, so it can't be used to min-max.
hooks.consume = (ctx, result) => {
  const s = ctx.character.stats;
  const weakest = ['strength', 'endurance', 'mobility'].sort((a, b) => s[a] - s[b])[0];
  result.yieldType = weakest;
  result.notes.push('⚖️ The pill flows to your weakest point: ' + weakest + '.');
  return result;
};

// Clarity Tea — percentage detox: great when you are very impure, weak when you are almost clean.
hooks.consume = (ctx, result) => {
  const imp = ctx.character.impurity;
  const remove = Math.min(imp, Math.max(3, Math.round(imp * 0.25 * 10) / 10));
  result.impurity = -remove;
  if (!remove) result.notes.push('🍵 Your meridians are already clear.');
  return result;
};

// Marrow Cleansing Pill — a harsh purge: the filth leaves, and some Qi leaves with it.
hooks.consume = (ctx, result) => {
  const loss = Math.min(2, ctx.character.stats.qi);
  result.yieldType = 'qi';
  result.yieldAmount = -loss;
  result.notes.push('🦴 The purge scours your marrow — ' + loss + ' Qi is lost with the filth.');
  return result;
};

// Tribulation Thunder Pill — turns impurity into breakthrough chance. Risky: it adds impurity too.
hooks.consume = (ctx, result) => {
  const bonus = Math.min(12, Math.floor(ctx.character.impurity / 5));
  result.breakthroughBonus = bonus;
  result.notes.push(bonus
    ? '⚡ The heavenly thunder feeds on your impurity: +' + bonus + '% Realm Breakthrough.'
    : '⚡ Too little impurity to call the thunder — no breakthrough bonus.');
  return result;
};

// Gate-Knocking Pill — can't be stockpiled early: it only works at the gate of the next realm.
hooks.consume = (ctx, result) => {
  const n = ctx.nextRealm;
  const ready = n && ctx.character.statTotal >= n.reqStats && ctx.character.stats.qi >= n.reqQi;
  if (!ready) {
    result.breakthroughBonus = 0;
    result.impurity += 10;
    result.notes.push('🚪 You knock, but the gate is not ready to open — the pill is wasted (+10 Impurity).');
  } else {
    result.notes.push('🚪 You stand at the gate — the pill opens the way.');
  }
  return result;
};
